/**
 * Static game data types: clubs, squads, kits, formations. Lead-owned, frozen after Wave 0.
 * Data values are generated by tools/gen-data.ts (DAT-01..04) and committed under src/data/.
 */

import type { FormationId, Foot, KitPattern, Role, TeamStyle } from './enums';

/** Squad member. Attributes 1..99. Outfield players carry low gk* values; keepers carry low outfield values. */
export interface PlayerData {
  /** Display name, e.g. "T. Okafor-Lind". Invented; screened against real footballers. */
  name: string;
  /** Short name for HUD (surname). */
  short: string;
  shirt: number;
  /** Natural position. */
  pos: Role;
  /** cm */
  height: number;
  foot: Foot;
  weakFoot: number;
  skillMoves: number;
  overall: number;
  acceleration: number; sprintSpeed: number; agility: number; ballControl: number; dribbling: number;
  shortPassing: number; longPassing: number; crossing: number; vision: number; finishing: number;
  shotPower: number; longShots: number; curve: number; heading: number; standingTackle: number;
  slidingTackle: number; interceptions: number; strength: number; stamina: number; composure: number;
  gkDiving: number; gkHandling: number; gkReflexes: number; gkPositioning: number; gkKicking: number;
}

/** Attribute keys copied into PlayerAttrs (same names). */
export const ATTRIBUTE_KEYS = [
  'acceleration', 'sprintSpeed', 'agility', 'ballControl', 'dribbling', 'shortPassing', 'longPassing', 'crossing',
  'vision', 'finishing', 'shotPower', 'longShots', 'curve', 'heading', 'standingTackle', 'slidingTackle',
  'interceptions', 'strength', 'stamina', 'composure', 'gkDiving', 'gkHandling', 'gkReflexes', 'gkPositioning', 'gkKicking',
] as const;
export type AttributeKey = (typeof ATTRIBUTE_KEYS)[number];

/** RGB colour as 0xRRGGBB. */
export type Rgb = number;

export interface Kit {
  shirt: Rgb;
  /** Second colour for the pattern. */
  shirt2: Rgb;
  pattern: KitPattern;
  shorts: Rgb;
  socks: Rgb;
  number: Rgb;
}

export interface Crest {
  /** Shape id 0..5 (shield, circle, diamond, hexagon, square, chevron). */
  shape: number;
  primary: Rgb;
  secondary: Rgb;
  /** Emblem id 0..9 (star, bolt, wave, ring, ...). */
  emblem: number;
  /** Stripe/split layout id 0..3. */
  layout: number;
}

export interface Club {
  id: number;
  name: string;
  /** Unique three-letter code. */
  code: string;
  city: string;
  /** Overall team rating 62..88. */
  rating: number;
  style: TeamStyle;
  formation: FormationId;
  home: Kit;
  away: Kit;
  keeper: Kit;
  /** Alternate keeper kit for keeper-vs-keeper clashes. */
  keeper2: Kit;
  crest: Crest;
  /** 18 players: indices 0..10 are starters in formation order (0 = keeper), 11..17 subs (one keeper among them). */
  squad: PlayerData[];
}

/** One formation position. Coordinates are normalised for a team attacking +x:
 *  nx in [-1, 1] (-1 own goal line, +1 opposition goal line), nz in [-1, 1] (-1 = far touchline z = -34, +1 near touchline z = +34).
 *  Facing +x, a player's right hand points to +z, so right-sided roles (RB, RM, RW) have nz > 0.
 *  For a team attacking -x, mirror both: x = -nx * 52.5, z = -nz * 34. */
export interface FormationSlot {
  role: Role;
  nx: number;
  nz: number;
}

export interface Formation {
  id: FormationId;
  name: string;
  /** 11 slots, index 0 = GK. */
  slots: FormationSlot[];
}
